import sys, json, time, platform
from pathlib import Path

START = time.time()
sys.path.append('storage/shared')

# Seeding utilities (via shim or package)
seed_tools_ok = True
try:
    from utilities.seed_tools import set_seed, make_rng, seed_from_str, mix_seed
except Exception:
    seed_tools_ok = False
    try:
        from seed_tools import set_seed, make_rng, seed_from_str, mix_seed  # shim
    except Exception:
        import random as _r, hashlib as _h
        def _u32(x): return int(x) & 0xFFFFFFFF
        def set_seed(s): _r.seed(_u32(s)); return _u32(s)
        def make_rng(s): set_seed(s); return None, _r.Random(_u32(s))
        def seed_from_str(s): return int(_h.sha256(s.encode()).hexdigest()[:8], 16)
        def mix_seed(a,b): return (_u32(a) ^ (_u32(b) + 0x9E3779B9)) & 0xFFFFFFFF

from coord.baseline_ring import simulate_ring_broadcast
from coord.metrics import basic_metrics
from coord.adaptive_ring import run_adaptive_ring

# Detect sampler availability
try:
    from utilities.adaptive_sampler import AdaptiveSampler  # noqa: F401
    adaptive_note = "adaptive_sampler available"
except Exception:
    adaptive_note = "adaptive_sampler not available"

base_seed = seed_from_str("Axiom-adaptive-ring-v1.1")
set_seed(base_seed)
_, _ = make_rng(base_seed)

cfg = {
    "N": 24,
    "max_steps": 400,
    "p0": 0.4,
    "sampler_cfg": {
        "initial_rate": 0.4,
        "adjustment_factor": 1.5,
        "target_delta": 0.10,
        "p_min": 0.2,
        "p_max": 1.0,
    },
    "replicates": 12
}

det_res = simulate_ring_broadcast(N=cfg["N"], p_send=1.0, max_steps=cfg["max_steps"])
det_met = basic_metrics(det_res)

runs = []
for r in range(cfg["replicates"]):
    run_seed = mix_seed(base_seed, r + 1)
    res = run_adaptive_ring(
        N=cfg["N"],
        max_steps=cfg["max_steps"],
        base_seed=run_seed,
        p0=cfg["p0"],
        sampler_cfg=cfg["sampler_cfg"],
        track_history=True,
    )
    runs.append(res)

import statistics as stats
def vals(key):
    v = [x["metrics"].get(key) for x in runs]
    return [x for x in v if x is not None]

agg = {}
for key in ["coverage", "time_to_full", "throughput_msgs_per_step"]:
    v = vals(key)
    if v:
        try:
            agg[key] = {"count": len(v), "mean": float(stats.fmean(v)), "min": float(min(v)), "max": float(max(v))}
        except Exception:
            v2 = [x for x in v if x is not None]
            agg[key] = {"count": len(v2), "mean": float(stats.fmean(v2)) if v2 else None, "min": float(min(v2)) if v2 else None, "max": float(max(v2)) if v2 else None}
    else:
        agg[key] = {"count": 0}

out_dir = Path("storage/shared/coord/results")
out_dir.mkdir(parents=True, exist_ok=True)
out_path = out_dir / "axiom_adaptive_ring_v1_1.json"

report = {
    "env": {
        "python": platform.python_version(),
        "implementation": platform.python_implementation(),
        "platform": platform.platform(),
        "seed_tools_imported": seed_tools_ok,
        "adaptive_sampler": adaptive_note,
    },
    "config": cfg,
    "deterministic_reference": {
        "steps_to_full": det_met["time_to_full"],
        "coverage": det_met["coverage"],
        "throughput_msgs_per_step": det_met["throughput_msgs_per_step"],
    },
    "runs": runs,
    "aggregate": agg,
}

with open(out_path, "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2, sort_keys=True)

END = time.time()
print("=== Adaptive Ring Broadcast v1.1 ===")
print(json.dumps({
    "artifact": str(out_path),
    "deterministic_time_to_full": det_met["time_to_full"],
    "adaptive_coverage_mean": report["aggregate"]["coverage"].get("mean"),
    "adaptive_time_to_full_mean": report["aggregate"]["time_to_full"].get("mean"),
    "controller_types": list({r.get("controller", {}).get("type", "?") for r in runs}),
    "adaptive_runs": len(report["runs"]),
    "timing_sec": round(END - START, 6),
}, indent=2))
print("Adaptive v1.1 complete.")
